import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Releasing and deployment","description":"","frontmatter":{},"headers":[],"relativePath":"releasing.md","filePath":"releasing.md"}'),n={name:"releasing.md"};function o(r,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="releasing-and-deployment" tabindex="-1">Releasing and deployment <a class="header-anchor" href="#releasing-and-deployment" aria-label="Permalink to &quot;Releasing and deployment&quot;">​</a></h1><p>The release model matches encrypt-rsa: generated VitePress output is committed under <code>docs/</code>, and npm publishing uses GitHub Actions OIDC with a version check.</p><h2 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-label="Permalink to &quot;GitHub Pages&quot;">​</a></h2><p>Source pages live in <code>documentation/</code>; <code>npm run docs</code> builds the site to <code>docs/</code>. The generated output includes <code>.nojekyll</code> and <code>CNAME</code> for <code>otp.js.org</code>.</p><p>Repository <strong>Settings → Pages → Deploy from a branch</strong> must use <strong>master /docs</strong>. Keep the custom domain <code>otp.js.org</code>.</p><p>CI rebuilds the docs and requires the generated output to match the committed site. GitHub Pages deploys that directory when changes reach master. No npm release is needed for a docs-only change.</p><h2 id="configure-npm-trusted-publishing" tabindex="-1">Configure npm trusted publishing <a class="header-anchor" href="#configure-npm-trusted-publishing" aria-label="Permalink to &quot;Configure npm trusted publishing&quot;">​</a></h2><p>In the npm package settings for <code>gen-totp</code>, add a GitHub Actions trusted publisher with:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Organization or user</td><td><code>miladezzat</code></td></tr><tr><td>Repository</td><td><code>gen-totp</code></td></tr><tr><td>Workflow filename</td><td><code>publish.yml</code></td></tr><tr><td>Environment</td><td>Leave blank</td></tr></tbody></table><p>The workflow uses Node.js 24, npm 11.13.0, and <code>id-token: write</code>. It publishes without <code>NPM_TOKEN</code>. Configure the trusted publisher before merging a version bump. After confirming trusted publication, remove the obsolete token from the repository if it is no longer used elsewhere.</p><h2 id="release-a-new-version" tabindex="-1">Release a new version <a class="header-anchor" href="#release-a-new-version" aria-label="Permalink to &quot;Release a new version&quot;">​</a></h2><ol><li>Choose the version appropriate for the compatibility changes and update the changelog.</li><li>Run <code>npm run release</code> or update package metadata using your normal release process.</li><li>Run the full validation commands, rebuild the docs, and commit all changed files, including <code>package-lock.json</code>.</li><li>Merge the reviewed release into master.</li></ol><p><code>publish.yml</code> first checks whether the exact stable local version already exists on npm. Existing versions skip publication, even if the <code>latest</code> tag has moved. Only an exact-version 404 permits comparison with npm latest: unpublished lower versions fail, and higher versions run lint, tests, package installation checks, and docs checks before publishing. Network errors, unexpected responses, and inconsistent metadata fail the gate without publishing.</p><p>After a successful publish, the workflow polls the exact npm version, installs it in an isolated consumer with lifecycle scripts disabled, and checks that its tarball integrity matches registry metadata. It verifies the declared runtime and type files, then runs CommonJS and native ESM consumers against RFC vectors and the new counter API. The existing-release path performs the same artifact checks. A registry timeout or broken artifact fails verification without publishing again. Inspect npm before retrying a release.</p><p>Exact-version metadata can appear before npm can install the version. The verifier revalidates cached registry information and retries temporary installation availability errors within the same deadline. Broken artifacts, integrity mismatches, and authentication failures still fail immediately.</p><h2 id="validate-locally" tabindex="-1">Validate locally <a class="header-anchor" href="#validate-locally" aria-label="Permalink to &quot;Validate locally&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-release.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/verify-release.js</span></span></code></pre></div><p>These commands do not publish a package. <code>check-release.js</code> reads npm metadata; <code>verify-release.js</code> also downloads and installs the exact version in a temporary directory, then removes it after checking the artifact. Run the verifier only after that version exists on npm. <code>npm run test:release</code> tests the gate, replication handling, and installed-artifact failure cases without publishing. Run <code>npm run build</code> first so its isolated consumer fixtures have runtime files.</p>`,18)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
